    for r in range(h):
        for c in range(w):
            if g[r][c] != 5:
                continue
            nbrs = []
            for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w:
                    nbrs.append((rr, cc, g[rr][cc]))
            zeros = [(rr, cc) for rr, cc, v in nbrs if v == 0]
            if len(zeros) >= 3:
                marks.extend(zeros)
    for r, c in marks:
        g[r][c] = 6
    return g
